let hp, hands=[], ac, oscs=[], gains=[], ready=false;
const NOTES = [261,294,330,392,440,131,147,165,196,220];
const TIPS = [4,8,12,16,20];

function setup(){
  createCanvas(windowWidth, windowHeight);
  let s = document.createElement('script');
  s.src = 'https://unpkg.com/ml5@1/dist/ml5.min.js';
  s.onload = () => {
    let cam = createCapture(VIDEO); cam.hide();
    hp = ml5.handPose({flipped:true});
    hp.detectStart(cam, r => hands=r);
    ready = true;
  };
  document.head.appendChild(s);
}

function draw(){
  background(13,27,42,18);
  if(!ready||!ac){ fill(255,80); textAlign(CENTER,CENTER); text(ready?'click to start':'loading ml5...', width/2, height/2); return }
  for(let g of gains) g.gain.setTargetAtTime(0, ac.currentTime, 0.05);
  for(let h of hands){
    let off = h.handedness==='Left' ? 5 : 0;
    for(let f=0; f<5; f++){
      let kp = h.keypoints[TIPS[f]];
      if(!kp) continue;
      let vol = map(kp.y, height*0.7, height*0.05, 0, 0.3, true);
      gains[off+f].gain.setTargetAtTime(vol, ac.currentTime, 0.04);
      noStroke();
      for(let r=60; r>0; r-=10){
        fill(off?180:255, map(f,0,4,80,220), off?255:80, vol*r*8);
        circle(kp.x, kp.y, r);
      }
    }
  }
}

function mousePressed(){
  if(!ready) return;
  if(ac) return ac.resume();
  ac = new AudioContext();
  for(let i=0; i<10; i++){
    let g=ac.createGain(); g.gain.value=0; g.connect(ac.destination); gains.push(g);
    let o=ac.createOscillator(); o.type='sine'; o.frequency.value=NOTES[i]; o.connect(gains[i]); o.start(); oscs.push(o);
  }
}

